@@ -1,8 +1,24 @@
 -- Переход со старого текстового status на нормализованный state.
 -- Старая колонка удаляется в 032, откатиться после неё будет нечем.

 ALTER TABLE visits ADD COLUMN state VARCHAR(16);

 CREATE INDEX idx_visits_state ON visits (clinic_id, state);
+
+UPDATE visits SET state = 'closed'
+WHERE status = 'закрыт';
+
+UPDATE visits SET state = 'cancelled'
+WHERE status = 'отменён';
+
+UPDATE visits SET state = 'open';
